  ('ecb9fcee-f4e0-4542-865f-feaa27a4d75f', 'exposicao-comemorativa-dos-50-anos-da-constituicao-da-republica-portuguesa-ecb9fc', 'Exposição comemorativa dos «50 anos da Constituição da República Portuguesa»', null, null, 'Dedicada ao constitucionalismo em Portugal, esta exposição percorre as principais Constituições — leis fundamentais que marcaram a evolução política, social e cultural do país. Reúne documentos do Arquivo Nacional da Torre do Tombo, colocando-os em diálogo com revistas literárias portuguesas do século XX, explorando a forma como os direitos fundamentais consagrados em 1976 foram pensados, debatidos e representados ao longo do tempo.', 'Dedicada ao constitucionalismo em Portugal, esta exposição percorre as principais Constituições — leis fundamentais que marcaram a evolução política, social e cultural do país. Reúne documentos do Arquivo Nacional da Torre do Tombo, colocando-os em diálogo com revistas literárias portuguesas do século XX, explorando a forma como os direitos fundamentais consagrados em 1976 foram pensados,…', 'torres-novas', null, 'Torres Novas', null, null, null, null, null, null, 'exposicoes', 0.95, array['exposicoes']::text[], '{}'::text[], null, null, '2026-04-24', '2026-10-22', false, null, null, false, null, null, null, null, null, null, false, false, false, false, null, 'https://cm-torresnovas.pt/media/com_eventbooking/images/thumbs/RT2810_ctz_expo_constituicao_VF.jpg', null, 'Exposição comemorativa dos «50 anos da Constituição da República Portuguesa»', 'published', 'scraper', 0.8, 'cm-torresnovas', 'eb-631', 'https://cm-torresnovas.pt/index.php/comunicacao/agenda/exposicoes/exposi%C3%A7%C3%A3o-comemorativa-dos-%C2%AB50-anos-da-constitui%C3%A7%C3%A3o-da-rep%C3%BAblica-portuguesa%C2%BB', 'a0181cd7633826045c9f1b403e7953b9393dc4e4ee24cd59152a462f0f53df6b', '9c5cab125e36b4319d9ccd6fcf758fd47a6103ceead44499de36dfc9958f0fcf', '2026-08-29T12:00:00.000Z', '2026-08-29T12:00:00.000Z'),
  ('cc46a641-1fb8-4caa-8116-d73c599051b7', '7-edicao-dos-passeios-socioculturais-seniores-cc46a6', '7.ª edição dos Passeios Socioculturais Seniores', null, null, 'O Município de Torres Novas promove, durante os meses de maio a setembro, a realização de mais uma edição dos Passeios Socioculturais Seniores, destinados a abranger toda a população sénior do concelho com idade igual ou superior a 65 anos, tendo este ano como destino Cascais e Belém (Lisboa). No caso dos cônjuges, é suficiente que apenas um tenha idade igual ou superior a 65 anos.', 'O Município de Torres Novas promove, durante os meses de maio a setembro, a realização de mais uma edição dos Passeios Socioculturais Seniores, destinados a abranger toda a população sénior do concelho com idade igual ou superior a 65 anos, tendo este ano como destino Cascais e Belém (Lisboa). No caso dos cônjuges, é suficiente que apenas um tenha idade igual ou superior a 65 anos.', 'torres-novas', null, 'Torres Novas', null, null, null, null, null, null, null, null, array['ar-livre']::text[], '{}'::text[], null, null, '2026-05-05', '2026-09-24', false, null, null, false, null, null, null, null, null, null, false, false, false, false, null, 'https://cm-torresnovas.pt/media/com_eventbooking/images/thumbs/RT2874_passeios-socioculturais-2026-1.jpg', null, '7.ª edição dos Passeios Socioculturais Seniores', 'published', 'scraper', 0.7, 'cm-torresnovas', 'eb-659', 'https://cm-torresnovas.pt/index.php/comunicacao/agenda/ar-livre/7-%C2%AA-edi%C3%A7%C3%A3o-dos-passeios-socioculturais-seniores', '77d82c6bf648940a86f4a05fda16038b37a5aa4f7102d8693685f07429e2578b', 'ad155d35885e34a48ce784af1d12304c2ceaa7a66993ad91229b1f7884a143f1', '2026-08-29T12:00:00.000Z', '2026-08-29T12:00:00.000Z'),
  ('7babc7e9-f174-4591-b211-a767f750f3a8', 'desporto-no-concelho-7babc7', 'Desporto no concelho', null, null, 'O Município de Torres Novas volta a promover, durante os meses de julho e agosto, um conjunto de atividades desportivas gratuitas ao ar livre, que decorrerão todos os sábados, às 9h30, em diferentes localidades do concelho.', 'O Município de Torres Novas volta a promover, durante os meses de julho e agosto, um conjunto de atividades desportivas gratuitas ao ar livre, que decorrerão todos os sábados, às 9h30, em diferentes localidades do concelho.', 'torres-novas', null, 'Torres Novas', null, null, null, null, null, null, 'desporto-natureza', 0.95, array['desporto']::text[], '{}'::text[], 'all_ages', null, '2026-07-04', '2026-08-29', false, null, 570, true, 0, null, 'Entrada livre', null, null, null, false, false, false, false, null, 'https://cm-torresnovas.pt/media/com_eventbooking/images/thumbs/Desporto_no_concelho_2026.jpg', null, 'Desporto no concelho', 'published', 'scraper', 0.85, 'cm-torresnovas', 'eb-692', 'https://cm-torresnovas.pt/index.php/comunicacao/agenda/desporto/desporto-no-concelho-2026', 'b53c178d47c73bd5ed010b4a5f060f513b9ffc79e991a4c4214275afd62a0d4a', '989953b6d1d1dbec67cb00bca833707b47992fff792b4574e9f0d10357cc1fe5', '2026-08-29T12:00:00.000Z', '2026-08-29T12:00:00.000Z'),
  ('95ff7e0f-5a79-4e60-b549-5a13aeab6099', 'cinema-o-fantasma-de-canterville-95ff7e', 'Cinema // O Fantasma de Canterville', null, null, 'Uma família americana muda-se para a tranquila mansão londrina de Canterville, mas rapidamente descobre que é assombrada por um fantasma.', 'Uma família americana muda-se para a tranquila mansão londrina de Canterville, mas rapidamente descobre que é assombrada por um fantasma.', 'torres-novas', null, 'Torres Novas', null, null, null, null, null, null, 'cinema', 0.95, array['cinema']::text[], '{}'::text[], 'family', null, '2026-08-29', '2026-08-29', false, null, null, false, null, null, null, null, null, null, false, false, false, false, null, 'https://cm-torresnovas.pt/media/com_eventbooking/images/thumbs/O_FANTASMA_DE_CANTERVILLE_Volver2026.jpg', null, 'Cinema // O Fantasma de Canterville', 'published', 'scraper', 0.85, 'cm-torresnovas', 'eb-700', 'https://cm-torresnovas.pt/index.php/comunicacao/agenda/cinema/cinema-o-fantasma-de-canterville', '73a0960135b37255a4e16d42ee83f40aa9b26b985783b492f9665d267d38caf2', 'd73ae819a1815044cef70d5b2ebd1ee833a9f5b7a3c9bb3e9648887fca7ffb9d', '2026-08-29T12:00:00.000Z', '2026-08-29T12:00:00.000Z'),
