  ('8c9d04a8-ae5e-4e3d-b5fa-b0b3f58baf96', 'visita-em-rede-parcerias-em-museus-uma-questao-de-sobrevivencia-8c9d04', 'Visita em rede - "Parcerias em museus, uma questão de sobrevivência?"', null, null, 'No dia 8 de setembro, o Museu Municipal Carlos Reis promove o encontro "Parcerias em museus, uma questão de sobrevivência?", um dia de visitas técnicas e debates para profissionais das diferentes áreas do património cultural, no âmbito do programa Visitas em Rede, uma iniciativa da Rede Portuguesa de Museus.', 'No dia 8 de setembro, o Museu Municipal Carlos Reis promove o encontro "Parcerias em museus, uma questão de sobrevivência?", um dia de visitas técnicas e debates para profissionais das diferentes áreas do património cultural, no âmbito do programa Visitas em Rede, uma iniciativa da Rede Portuguesa de Museus.', 'torres-novas', 'museu-carlos-reis', 'Torres Novas', null, null, null, null, null, null, 'exposicoes', 0.4, array['formacao-atelier-oficinas']::text[], '{}'::text[], null, null, '2026-09-08', '2026-09-08', false, null, null, false, null, null, null, null, null, null, false, false, false, false, null, 'https://cm-torresnovas.pt/media/com_eventbooking/images/thumbs/Visita_em_rede_2026.jpg', null, 'Visita em rede - "Parcerias em museus, uma questão de sobrevivência?"', 'published', 'scraper', 1, 'cm-torresnovas', 'eb-694', 'https://cm-torresnovas.pt/index.php/comunicacao/agenda/formacao-atelier-oficinas/visita-em-rede-parcerias-em-museus-uma-questao-de-sobrevivencia', 'cf8980b6be2816ec596ec4c42875a9757b06baaa97d453f9995fdaf8f5c3b1ea', '227c3aa477e84f9a967ab0d5f4ebdf78fcf93457c4501429ef194b9a375e3c28', '2026-08-29T12:00:00.000Z', '2026-08-29T12:00:00.000Z'),
