  ('8e83e22e-9992-4e6a-bf86-65c8f812fb31', 'congresso-do-desporto-8e83e2', 'Congresso do Desporto', null, null, 'A V edição do Congresso do Desporto, que decorre em 2026, reúne 11 municípios do Médio Tejo numa programação dedicada à reflexão e ao debate sobre diferentes dimensões do fenómeno desportivo...', 'A V edição do Congresso do Desporto, que decorre em 2026, reúne 11 municípios do Médio Tejo numa programação dedicada à reflexão e ao debate sobre diferentes dimensões do fenómeno desportivo...', 'torres-novas', null, 'Torres Novas', null, null, null, null, null, null, 'desporto-natureza', 0.95, array['desporto']::text[], '{}'::text[], null, null, '2026-09-18', '2026-09-18', false, null, null, false, null, null, null, null, null, null, false, false, false, false, null, 'https://cm-torresnovas.pt/media/com_eventbooking/images/thumbs/Congresso_do_Desporto_2026_TN.jpg', null, 'Congresso do Desporto', 'published', 'scraper', 0.85, 'cm-torresnovas', 'eb-714', 'https://cm-torresnovas.pt/index.php/comunicacao/agenda/desporto/congresso-do-desporto-2026', '6798d16044b6a7cb84bbf48efb3142ba9939ea30b9086511152d02e9d5f80999', '404124c6f36c08ffbe1e0935b2c55bbea564db85307a8dcb1f5aca158ad795e3', '2026-08-29T12:00:00.000Z', '2026-08-29T12:00:00.000Z'),
  ('8856d96f-8398-4572-987e-603597011744', 'teatro-a-mulher-do-meu-marido-8856d9', 'Teatro // A Mulher do Meu Marido', null, null, '“A Mulher do Meu Marido" é uma comédia sobre Gil e Afonso, um casal que vive em Lisboa, cuja rotina é abalada quando o conservador pai de Afonso decide visitá-lo para conhecer a suposta "mulher" do filho.', '“A Mulher do Meu Marido" é uma comédia sobre Gil e Afonso, um casal que vive em Lisboa, cuja rotina é abalada quando o conservador pai de Afonso decide visitá-lo para conhecer a suposta "mulher" do filho.', 'torres-novas', null, 'Torres Novas', null, null, null, null, null, null, 'teatro', 0.95, array['teatro']::text[], '{}'::text[], null, null, '2026-09-19', '2026-09-19', false, null, null, false, null, null, null, null, null, null, false, false, false, false, null, 'https://cm-torresnovas.pt/media/com_eventbooking/images/thumbs/A_MULHER_DO_MEU_MARIDO_Volver2026.jpg', null, 'Teatro // A Mulher do Meu Marido', 'published', 'scraper', 0.85, 'cm-torresnovas', 'eb-702', 'https://cm-torresnovas.pt/index.php/comunicacao/agenda/teatro/teatro-a-mulher-do-meu-marido', '89ebaf428bfb97841fdd15a6708ec8ba6345e42044b4401080531347bbe0b9ad', '0b0544148f87d824afb2456d71ec8bc8d4fb5c14004961526485f5b19dc21374', '2026-08-29T12:00:00.000Z', '2026-08-29T12:00:00.000Z'),
  ('af550855-28cc-47eb-af8b-ef87ff0caa4a', 'musica-encontro-de-bandas-filarmonicas-do-concelho-de-torres-novas-af5508', 'Música // Encontro de Bandas Filarmónicas do concelho de Torres Novas', null, null, 'O Encontro de Bandas Filarmónicas volta a reunir, em Torres Novas, várias bandas da região para celebrar a tradição filarmónica e o seu papel cultural e social nas comunidades.', 'O Encontro de Bandas Filarmónicas volta a reunir, em Torres Novas, várias bandas da região para celebrar a tradição filarmónica e o seu papel cultural e social nas comunidades.', 'torres-novas', null, 'Torres Novas', null, null, null, null, null, null, 'musica', 0.95, array['musica']::text[], '{}'::text[], null, null, '2026-09-20', '2026-09-20', false, null, null, false, null, null, null, null, null, null, false, false, false, false, null, 'https://cm-torresnovas.pt/media/com_eventbooking/images/thumbs/ENCONTRO_BANDAS_Volver2026.jpg', null, 'Música // Encontro de Bandas Filarmónicas do concelho de Torres Novas', 'published', 'scraper', 0.85, 'cm-torresnovas', 'eb-707', 'https://cm-torresnovas.pt/index.php/comunicacao/agenda/musica/m%C3%BAsica-encontro-de-bandas-filarm%C3%B3nicas-do-concelho-de-torres-novas', 'c7d6610ee147f727f41fc7b01d3ea9776eb1d1e9c8c2369c21cfd68bb2179b04', '536b3d191edd246cc56b86b98a39566751480c26090a50023aaa319932bfe604', '2026-08-29T12:00:00.000Z', '2026-08-29T12:00:00.000Z'),
