  ('12ebcb23-eee0-4b0e-8e97-d575beb39c0f', 'musica-e-danca-encontro-de-ranchos-folcloricos-do-concelho-de-torres-novas-12ebcb', 'Música e Dança // Encontro de Ranchos Folclóricos do concelho de Torres Novas', null, null, 'Em formato de workshop, este encontro propõe uma partilha viva de tradições, usos e costumes, evidenciando tanto os elementos comuns como a riqueza da diversidade presente no trajar, no cantar e no dançar dos diferentes grupos participantes.', 'Em formato de workshop, este encontro propõe uma partilha viva de tradições, usos e costumes, evidenciando tanto os elementos comuns como a riqueza da diversidade presente no trajar, no cantar e no dançar dos diferentes grupos participantes.', 'torres-novas', null, 'Torres Novas', null, null, null, null, null, null, 'musica', 0.95, array['musica']::text[], '{}'::text[], null, null, '2026-09-26', '2026-09-26', false, null, null, false, null, null, null, null, null, null, false, false, false, false, null, 'https://cm-torresnovas.pt/media/com_eventbooking/images/thumbs/ENCONTRO_RANCHOS_Volver2026.jpg', null, 'Música e Dança // Encontro de Ranchos Folclóricos do concelho de Torres Novas', 'published', 'scraper', 0.85, 'cm-torresnovas', 'eb-706', 'https://cm-torresnovas.pt/index.php/comunicacao/agenda/musica/m%C3%BAsica-e-dan%C3%A7a-encontro-de-ranchos-folcl%C3%B3ricos-do-concelho-de-torres-novas', '2ee2d241fb26ee772d1a7201ce5c7c3b7d7c0ff2ab508726d7c744ecc2cbaeca', '66123b7b5994c95fd8ad3b327b034e850c3a397a9be65e2a059b475a754f7ac8', '2026-08-29T12:00:00.000Z', '2026-08-29T12:00:00.000Z'),
  ('8f42c6bd-5530-47b6-b7f1-b18c808ade3e', 'musica-vitoria-faria-ed-woiski-8f42c6', 'Música // Vitoria Faria & Ed Woiski', null, null, 'Vitória Faria, cantora, compositora e acordeonista brasileira, junta-se a Ed Woiski num projeto que cruza tradição e contemporaneidade da música brasileira com influências do jazz, tango, fado e ritmos africanos.', 'Vitória Faria, cantora, compositora e acordeonista brasileira, junta-se a Ed Woiski num projeto que cruza tradição e contemporaneidade da música brasileira com influências do jazz, tango, fado e ritmos africanos.', 'torres-novas', null, 'Torres Novas', null, null, null, null, null, null, 'musica', 0.95, array['musica']::text[], '{}'::text[], null, null, '2026-09-26', '2026-09-26', false, null, null, false, null, null, null, null, null, null, false, false, false, false, null, 'https://cm-torresnovas.pt/media/com_eventbooking/images/thumbs/VITORIA_FARIA_Volver2026.jpg', null, 'Música // Vitoria Faria & Ed Woiski', 'published', 'scraper', 0.85, 'cm-torresnovas', 'eb-703', 'https://cm-torresnovas.pt/index.php/comunicacao/agenda/musica/m%C3%BAsica-vitoria-faria-ed-woiski', 'b5e10ce66d18c982b9cdf9df45a342b973082a05a3391d966e511822c1d0774a', '839d4c0d88c969c8b44790ae54274c2c656bfde9134039251dededc205f07d80', '2026-08-29T12:00:00.000Z', '2026-08-29T12:00:00.000Z'),
  ('b30d6a57-7b97-413f-9811-1adae96bf493', '39-feira-nacional-dos-frutos-secos-b30d6a', '39.ª Feira Nacional dos Frutos Secos', null, null, 'O Município de Torres Novas promove, de 1 a 5 de outubro, a 39.ª edição da Feira Nacional dos Frutos Secos, que terá lugar na Praça 5 de Outubro e na Praça dos Claras, em pleno centro histórico da cidade...', 'O Município de Torres Novas promove, de 1 a 5 de outubro, a 39.ª edição da Feira Nacional dos Frutos Secos, que terá lugar na Praça 5 de Outubro e na Praça dos Claras, em pleno centro histórico da cidade...', 'torres-novas', null, 'Praça 5 de Outubro e Praça dos Claras, Torres Novas', null, null, null, null, null, null, 'feiras-mercados', 0.7, array['festas-e-feiras']::text[], '{}'::text[], null, null, '2026-10-01', '2026-10-05', false, null, null, false, null, null, null, null, null, null, false, false, false, false, null, 'https://cm-torresnovas.pt/media/com_eventbooking/images/thumbs/Feira_Frutos_Secos_2026.jpg', null, '39.ª Feira Nacional dos Frutos Secos', 'published', 'scraper', 0.85, 'cm-torresnovas', 'eb-732', 'https://cm-torresnovas.pt/index.php/comunicacao/agenda/festas-e-feiras/39-feira-nacional-dos-frutos-secos', '3a70ff49157b2952ede8d9417fac8fc53a68b9ad0cb77830f64dd64100d49acb', 'fd3b0ab8a21fa87670091930dfb0ff1f1d48603368da31ae1b813e3a7c3bad0e', '2026-08-29T12:00:00.000Z', '2026-08-29T12:00:00.000Z'),
  ('84bc6b32-d4e7-4604-a386-980d0ddc43a6', 'magia-ensemble-magia-contemporanea-84bc6b', 'Magia // Ensemble Magia Contemporânea', null, null, 'Três mágicos contemporâneos, Zé Mágico, José Marques Antunes e Francisco Mousinho, com estilos e linguagens distintas, unem-se num espetáculo pensado para toda a família, onde a criatividade, a interação e a surpresa desafiam os limites entre o real e o impossível...', 'Três mágicos contemporâneos, Zé Mágico, José Marques Antunes e Francisco Mousinho, com estilos e linguagens distintas, unem-se num espetáculo pensado para toda a família, onde a criatividade, a interação e a surpresa desafiam os limites entre o real e o impossível...', 'torres-novas', null, 'Torres Novas', null, null, null, null, null, null, null, null, array['outros-eventos']::text[], '{}'::text[], 'family', null, '2026-10-09', '2026-10-09', false, null, null, false, null, null, null, null, null, null, false, false, false, false, null, 'https://cm-torresnovas.pt/media/com_eventbooking/images/thumbs/MAGIA_Volver2026.jpg', null, 'Magia // Ensemble Magia Contemporânea', 'published', 'scraper', 0.75, 'cm-torresnovas', 'eb-708', 'https://cm-torresnovas.pt/index.php/comunicacao/agenda/outros-eventos/magia-ensemble-magia-contempor%C3%A2nea', '35cbfd655b2f63af8817e7d5a2899ad6000eef263672e9dafb93a1a7a46b017f', 'fa0093719f8b49043332d6d0bd39747d263f16de1561783c7c5b48682af13a5b', '2026-08-29T12:00:00.000Z', '2026-08-29T12:00:00.000Z'),
  ('30cc3cb2-cb5f-499b-989f-e96ea565366b', 'trail-do-almonda-2026-30cc3c', 'Trail do Almonda 2026', null, null, 'A 16.ª edição do Trail do Almonda, inicialmente prevista para o dia 4 de julho de 2026 e adiada devido às condições meteorológicas adversas, realiza-se no próximo dia 11 de outubro, com partida e chegada junto ao Centro Escolar da Serra d’Aire, freguesia de Pedrógão, concelho de Torres Novas.', 'A 16.ª edição do Trail do Almonda, inicialmente prevista para o dia 4 de julho de 2026 e adiada devido às condições meteorológicas adversas, realiza-se no próximo dia 11 de outubro, com partida e chegada junto ao Centro Escolar da Serra d’Aire, freguesia de Pedrógão, concelho de Torres Novas.', 'torres-novas', null, 'Centro Escolar da Serra d''Aire, Pedrógão', null, null, null, null, null, null, 'desporto-natureza', 0.95, array['desporto']::text[], '{}'::text[], null, null, '2026-10-11', '2026-10-11', false, null, null, false, null, null, null, null, null, null, false, false, false, false, null, 'https://cm-torresnovas.pt/media/com_eventbooking/images/thumbs/Trail-Almonda-CartazA3-outubro.jpg', null, 'Trail do Almonda 2026', 'published', 'scraper', 0.85, 'cm-torresnovas', 'eb-663', 'https://cm-torresnovas.pt/index.php/comunicacao/agenda/desporto/trail-do-almonda-2026', 'dd94f7fb21eee84c73a1bff4226b0d0ac2f9dcde521ac991af302efbda4bee97', '4196217f67ea15b2980b05c7aa104e47152dbc655fa06d50c459214b4cdb0862', '2026-08-29T12:00:00.000Z', '2026-08-29T12:00:00.000Z'),
  ('854598f4-30e3-442f-b0bf-7a15bb36b602', 'musica-banda-da-armada-854598', 'Música // Banda da Armada', null, null, 'Segundo fontes históricas, já na primeira metade do século XVIII existia na Armada uma “música marcial” intitulada “charamela”. Ao longo dos tempos a Banda da Armada tem desenvolvido um trabalho de grande interesse público, tanto ao nível do cerimonial militar e do protocolo de Estado, como no âmbito cultural, destacando-se inúmeras atuações em Portugal continental e insular, assim como em França, Bélgica, Alemanha, Brasil e Estados Unidos da América...', 'Segundo fontes históricas, já na primeira metade do século XVIII existia na Armada uma “música marcial” intitulada “charamela”. Ao longo dos tempos a Banda da Armada tem desenvolvido um trabalho de grande interesse público, tanto ao nível do cerimonial militar e do protocolo de Estado, como no âmbito cultural, destacando-se inúmeras atuações em Portugal continental e insular, assim como em…', 'torres-novas', null, 'Torres Novas', null, null, null, null, null, null, 'musica', 0.95, array['musica']::text[], '{}'::text[], null, null, '2026-10-28', '2026-10-28', false, null, null, false, null, null, null, null, null, null, false, false, false, false, null, 'https://cm-torresnovas.pt/media/com_eventbooking/images/thumbs/BANDA_DA_ARMADA_Volver2026.jpg', null, 'Música // Banda da Armada', 'published', 'scraper', 0.85, 'cm-torresnovas', 'eb-709', 'https://cm-torresnovas.pt/index.php/comunicacao/agenda/musica/m%C3%BAsica-banda-da-armada', '1cc9d004495f756eb785f2eb330a8ee567811229080829de131d46946ef9bd13', 'da2194718d8e9c36f998f0f3b56cf2905c0462b9fa07f5e7e881509069394798', '2026-08-29T12:00:00.000Z', '2026-08-29T12:00:00.000Z'),
  ('4e741bbc-b65b-4e47-965a-f6aa161619e0', 'teatro-ninguem-pediu-mas-eu-conto-4e741b', 'Teatro // Ninguém pediu, mas eu conto!', null, null, 'Há histórias que ficam guardadas numa gaveta. Outras escapam-se sem aviso, no meio de uma conversa, de uma música ou de uma memória mal contada...', 'Há histórias que ficam guardadas numa gaveta. Outras escapam-se sem aviso, no meio de uma conversa, de uma música ou de uma memória mal contada...', 'torres-novas', null, 'Torres Novas', null, null, null, null, null, null, 'teatro', 0.95, array['teatro']::text[], '{}'::text[], null, null, '2026-10-30', '2026-10-30', false, null, null, false, null, null, null, null, null, null, false, false, false, false, null, 'https://cm-torresnovas.pt/media/com_eventbooking/images/thumbs/NINGUEM_PEDIU_MAS_EU_CONTO_Volver2026.jpg', null, 'Teatro // Ninguém pediu, mas eu conto!', 'published', 'scraper', 0.85, 'cm-torresnovas', 'eb-710', 'https://cm-torresnovas.pt/index.php/comunicacao/agenda/teatro/teatro-ningu%C3%A9m-pediu,-mas-eu-conto', 'fefe1c46ab457ef87508a80f1a4e297c23fd5c1acf64811ebb391c4352e5a6a2', 'd786573671fd519c6d5d977a89462271f35e819a48a138a3c407785c40084878', '2026-08-29T12:00:00.000Z', '2026-08-29T12:00:00.000Z'),
