-- ---------------------------------------------------------------------------
-- A fonte diz o que se passou.
-- ---------------------------------------------------------------------------
update public.sources
   set notes = coalesce(notes, '') || ' IMPORTAÇÃO POR INSTANTÂNEO 2026-08-29: o dono guardou as três páginas da agenda no browser de casa e os 22 eventos entraram pela ferramenta `packages/ingest/src/instantaneo.ts`, que serve os ficheiros ao adaptador desta fonte — mesmos seletores, mesmas chaves `eb-N`. Quando o acesso for autorizado, a primeira recolha reconhece-os pela chave e atualiza-os. As páginas guardadas estão em `instantaneos/cm-torresnovas-2026-08-29/`.',
       updated_at = now()
 where id = 'cm-torresnovas';

-- ---------------------------------------------------------------------------
-- O que tem de continuar verdade.
-- ---------------------------------------------------------------------------
do $$
declare
  n integer;
begin
  select count(*) into n from public.events where source_id = 'cm-torresnovas';
  assert n = 22, format('%s eventos de Torres Novas, esperavam-se 22', n);

  -- Todo o evento diz onde é. A base já o exige; dizê-lo aqui é o que
  -- transforma um erro de gravação numa mensagem que se percebe.
  select count(*) into n
    from public.events
   where source_id = 'cm-torresnovas'
     and venue_id is null and location_name is null;
  assert n = 0, format('%s eventos de Torres Novas sem sítio nenhum', n);

  -- Quatro eventos acontecem num espaço do catálogo: um no Museu Carlos Reis,
  -- três na Biblioteca Gustavo Pinto Lopes.
  select count(*) into n
    from public.events
   where source_id = 'cm-torresnovas' and venue_id is not null;
  assert n = 4, format('%s eventos ligados a um espaço, esperavam-se 4', n);

  -- Cada campo escrito à mão ficou bloqueado. Sem isto, a recolha do dia em
  -- que a fonte abrir apaga o resumo e devolve «Torres Novas» ao sítio.
  select count(*) into n
    from public.manual_overrides
   where actor = 'instantâneos de Torres Novas, 2026-08-29';
  assert n = 51, format('%s bloqueios escritos, esperavam-se 51', n);

  -- A fonte fica desligada. É o ponto todo: isto não é o automatismo.
  select count(*) into n from public.sources
   where id = 'cm-torresnovas' and is_enabled;
  assert n = 0, 'cm-torresnovas ficou ligada — o WAF continua lá e a recolha vai falhar todas as noites';
end $$;

commit;
